import{_ as t,H as a,f as n,i as s}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"复习课（二） | 管理规划","description":"","frontmatter":{},"headers":[{"level":2,"title":"（二）管理规划","slug":"二-管理规划","link":"#二-管理规划","children":[]}],"relativePath":"技术管理实战36讲/复习课（二）-管理规划.md","filePath":"技术管理实战36讲/复习课（二）-管理规划.md","lastUpdated":1779820334000}'),i={name:"技术管理实战36讲/复习课（二）-管理规划.md"};function r(E,e,o,g,p,b){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="复习课-二-管理规划" tabindex="-1">复习课（二） | 管理规划 <a class="header-anchor" href="#复习课-二-管理规划" aria-label="Permalink to &quot;复习课（二） | 管理规划&quot;">​</a></h1><hr><p>继上一篇的“ <strong>角色认知</strong>”之后，接下来我们继续来复习“管理方法论”的另外一个方面： <strong>管理规划</strong>。</p><h2 id="二-管理规划" tabindex="-1">（二）管理规划 <a class="header-anchor" href="#二-管理规划" aria-label="Permalink to &quot;（二）管理规划&quot;">​</a></h2><p>管理规划，具体该怎么操作呢？</p><p>这里可以类比这样一个问题：一辆马车交给你，在驾驶它上路之前，你先做哪件事呢？</p><p>那，“驾驶马车”和管理规划就要明确回答了下面这四个问题：</p><ol><li>这是辆什么车？ <strong>VS</strong> 你团队是干什么的？</li><li>你要把这辆车拉到哪里去？ <strong>VS</strong> 你团队想做出什么成果？</li><li>你有哪些马，它们情况如何？ <strong>VS</strong> 你依靠什么样的团队？</li><li>你选择走哪条路？ <strong>VS</strong> 你需要投入哪些资源？</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67690/9c0aa22b3c1e49ed55bb5ce74ffd4c72.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67690/9c0aa22b3c1e49ed55bb5ce74ffd4c72.jpg" alt=""></a></p><p>“马车模型之规划四要素”</p><p>这就是相互关联且动态平衡的 <strong>管理规划四要素：职能、目标、团队和路径</strong>。其中，最稳定的要素是职能，它是管理的起点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67690/9857429561b5489bd9e9a9fbe3046a60.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67690/9857429561b5489bd9e9a9fbe3046a60.png" alt=""></a></p><p>“规划四要素”关系图</p><p>（来自 <a href="https://time.geekbang.org/column/article/18029" target="_blank" rel="noreferrer">第11篇《我刚开始带团队，从哪里着手呢？》</a>）</p><p><strong>1. 明确职能</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67690/e74801838f37fdb1dc3ab5b1f3c9e45a.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67690/e74801838f37fdb1dc3ab5b1f3c9e45a.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/18040" target="_blank" rel="noreferrer">第12篇《如何界定我团队是干什么的呢？》</a></p><p><strong>2. 设定目标</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67690/39ba6ac5ff38f73162eddd99d7963717.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67690/39ba6ac5ff38f73162eddd99d7963717.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67690/0cfcbe9b4b24567e9b4615a41681fa1a.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67690/0cfcbe9b4b24567e9b4615a41681fa1a.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/20712" target="_blank" rel="noreferrer">第13篇《如何为团队设定合理的目标呢？》</a></p><p><strong>3. 盘点团队</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67690/f2c55bcd95788cb63078decd74630557.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67690/f2c55bcd95788cb63078decd74630557.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/39779" target="_blank" rel="noreferrer">第14篇《如何来规划团队的组织结构呢？》</a></p><p><strong>4. 选择路径</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67690/41ba98535aeb254dd0276424e006a503.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67690/41ba98535aeb254dd0276424e006a503.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/39973" target="_blank" rel="noreferrer">第15篇《我都要申请哪些资源呢？》</a></p><p>至此，我们就复习完了管理规划的全部四个要素：职能、目标、团队和路径。详细内容也可戳文中所附的链接。</p><hr>',29)])])}const h=t(i,[["render",r]]);export{c as __pageData,h as default};
